// ================= TRANSACTIONAL CONCURRENCY & IDEMPOTENCY ENGINE =================

async function withPostgresTransaction<T>(
  callback: (client: pg.PoolClient) => Promise<T>,
  idempotencyKey?: string
): Promise<T> {
  if (!dbPool) {
    throw new Error('DATABASE_URL no configurada para transacciones PostgreSQL');
  }
  const client = await dbPool.connect();
  const rawClientQuery = client.query.bind(client);
  (client as any).query = (text: any, params?: any) => {
    totalPostgresQueriesCount++;
    return rawClientQuery(text, params);
  };
  try {
    await client.query('BEGIN');

    // 0. Acquire shared advisory lock to prevent concurrent restore while permitting high-throughput concurrent normal operations
    await client.query('SELECT pg_advisory_xact_lock_shared(987654321)');

    // 1. If an idempotencyKey is provided, atomically acquire row lock / register idempotency intent in PostgreSQL
    if (idempotencyKey) {
      const initRes = await client.query(
        `INSERT INTO operaciones_idempotencia (clave, respuesta, fecha)
         VALUES ($1, '{"__status":"pending"}'::jsonb, CURRENT_TIMESTAMP)
         ON CONFLICT (clave) DO UPDATE
           SET clave = EXCLUDED.clave
         RETURNING (xmax = 0) AS is_inserted, respuesta`,
        [idempotencyKey]
      );

      const row = initRes.rows[0];
      const isInserted = row?.is_inserted;
      const existingResp = row?.respuesta;

      // If the row already existed and has a completed response (not pending), return it immediately
      if (!isInserted && existingResp && existingResp.__status !== 'pending') {
        await client.query('COMMIT');
        return existingResp as T;
      }
    }

    // 2. Execute transactional business logic
    const result = await callback(client);

    // 3. Atomically persist final idempotency record within the SAME PostgreSQL transaction BEFORE COMMIT
    if (idempotencyKey) {
      await client.query(
        `INSERT INTO operaciones_idempotencia (clave, respuesta, fecha)
         VALUES ($1, $2, CURRENT_TIMESTAMP)
         ON CONFLICT (clave) DO UPDATE SET respuesta = EXCLUDED.respuesta`,
        [idempotencyKey, JSON.stringify(result)]
      );
    }

    // 4. Commit financial changes AND idempotency record together
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackErr) {
      console.error('[PostgreSQL Rollback Error]:', rollbackErr);
    }
    throw err;
  } finally {
    client.release();
  }
}

// ============================================================================
// FASE 4.13: SESSION CACHE & LOAD OPTIMIZATION ENGINE
// ============================================================================

export interface CachedDomain<T = any> {
  data: T;
  cachedAt: number;
}

export interface StudentSessionEntry {
  studentId: string;
  version: number;
  lastUpdated: number;
  company?: CachedDomain;
  acquisitions?: CachedDomain;
  transfers?: CachedDomain;
  employees?: CachedDomain;
  electricityContracts?: CachedDomain;
  electricityBills?: CachedDomain;
  floorPlans?: CachedDomain;
  telecomContracts?: CachedDomain;
  telecomInvoices?: CachedDomain;
  officeOrders?: CachedDomain;
  vehicles?: CachedDomain;
  rawMaterialOrders?: CachedDomain;
  rawMaterialInventory?: CachedDomain;
  upcomingPayments?: CachedDomain;
  courtLawsuits?: CachedDomain;
}

export interface GlobalCatalogCache {
  properties?: CachedDomain;
  jobListings?: CachedDomain;
  rawMaterialAnnouncements?: CachedDomain;
  users?: CachedDomain;
  studentsList?: CachedDomain;
}

const studentSessionCache = new Map<string, StudentSessionEntry>();
const globalCatalogCache: GlobalCatalogCache = {};

const SESSION_CACHE_TTL_MS = 60 * 1000;   // 60s TTL for student domain caches
const CATALOG_CACHE_TTL_MS = 120 * 1000; // 120s TTL for catalogs

function getStudentSession(studentId: string): StudentSessionEntry {
  const sId = String(studentId);
  let session = studentSessionCache.get(sId);
  if (!session) {
    session = {
      studentId: sId,
      version: 1,
      lastUpdated: Date.now()
    };
    studentSessionCache.set(sId, session);
  }
  return session;
}

function invalidateStudentSessionCache(studentId?: string, domain?: keyof StudentSessionEntry) {
  if (!studentId) return;
  const sId = String(studentId);
  const session = studentSessionCache.get(sId);
  if (session) {
    session.version = (session.version || 0) + 1;
    session.lastUpdated = Date.now();
    if (domain && domain !== 'studentId' && domain !== 'version' && domain !== 'lastUpdated') {
      delete (session as any)[domain];
    } else {
      studentSessionCache.delete(sId);
    }
  }
  // Public user listing might be impacted if user details/balance changed
  delete globalCatalogCache.users;
  delete globalCatalogCache.studentsList;
}

function invalidateGlobalCatalogCache(key?: keyof GlobalCatalogCache) {
  if (key) {
    delete globalCatalogCache[key];
  } else {
    delete globalCatalogCache.properties;
    delete globalCatalogCache.jobListings;
    delete globalCatalogCache.rawMaterialAnnouncements;
    delete globalCatalogCache.users;
    delete globalCatalogCache.studentsList;
  }
}

function clearAllSessionCaches() {
  studentSessionCache.clear();
  invalidateGlobalCatalogCache();
}

const inFlightOperations = new Map<string, Promise<any>>();

async function executeWithIdempotency<T>(
  key: string,
  operation: (idemKey: string) => Promise<T>
): Promise<T> {
  // 1. If an identical operation is already in-flight in this Node process, await its existing promise
  if (inFlightOperations.has(key)) {
    return (await inFlightOperations.get(key)) as T;
  }

  // 2. Build the async execution promise
  const inFlightPromise = (async () => {
    // Check if already committed in PostgreSQL (e.g. past request or across server restarts)
    if (dbPool) {
      try {
        const existing = await safeDbQuery('SELECT respuesta FROM operaciones_idempotencia WHERE clave = $1', [key]);
        if (existing && existing.rows && existing.rows.length > 0) {
          const resp = existing.rows[0].respuesta;
          if (resp && resp.__status !== 'pending') {
            return resp as T;
          }
        }
      } catch (e) {
        // Non-fatal, continue execution
      }
    }

    // Execute the transactional operation
    const result = await operation(key);

    // Extra safety: ensure recorded asynchronously without blocking the response
    if (dbPool) {
      safeDbQuery(
        `INSERT INTO operaciones_idempotencia (clave, respuesta, fecha) 
         VALUES ($1, $2, CURRENT_TIMESTAMP) 
         ON CONFLICT (clave) DO UPDATE SET respuesta = EXCLUDED.respuesta`,
        [key, JSON.stringify(result)]
      ).catch(() => {});
    }

    return result;
  })();

  // Prevent Node.js process crashes due to unhandled promise rejections when an operation fails
  inFlightPromise.catch(() => {});

  // Synchronously register promise into inFlightOperations before any async turn
  inFlightOperations.set(key, inFlightPromise);

  try {
    return await inFlightPromise;
  } catch (err) {
    inFlightOperations.delete(key);
    throw err;
  } finally {
    setTimeout(() => {
      inFlightOperations.delete(key);
    }, 10000);
  }
}

// Sync helper functions for Supabase
async function syncAccountToSupabase(id: string, alumno: string, saldo: number, usuario?: string, password?: string, accountNumber?: string, role?: string, level?: number) {
  if (!dbPool) return;
  try {
    const numSaldo = Number(Number(saldo).toFixed(2));
    // 1. Direct update if row already exists by id or username
    const updateRes = await safeDbQuery(
      `UPDATE cuentas 
       SET saldo = $1, 
           alumno = COALESCE($2, alumno),
           role = COALESCE($3, role),
           level = COALESCE($4, level)
       WHERE id = $5 OR (usuario IS NOT NULL AND usuario = $6)`,
      [numSaldo, alumno || null, role || null, level || null, id, usuario || null]
    );

    // 2. If row does not exist yet, insert it cleanly
    if (!updateRes || updateRes.rowCount === 0) {
      await safeDbQuery(
        `INSERT INTO cuentas (id, alumno, saldo, usuario, password, account_number, role, level)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
         ON CONFLICT (id) DO UPDATE SET 
           alumno = EXCLUDED.alumno, 
           saldo = EXCLUDED.saldo,
           usuario = COALESCE(EXCLUDED.usuario, cuentas.usuario),
           password = COALESCE(EXCLUDED.password, cuentas.password),
           account_number = COALESCE(EXCLUDED.account_number, cuentas.account_number),
           role = COALESCE(EXCLUDED.role, cuentas.role),
           level = COALESCE(EXCLUDED.level, cuentas.level)`,
        [id, alumno, numSaldo, usuario || null, password || null, accountNumber || null, role || 'student', level || 1]
      );
    }
  } catch (e) {
    console.error('[Supabase DB] Error syncing account to Supabase:', e);
    throw e;
  }
}

async function syncCompanyProfileToSupabase(profile: CompanyProfile) {
  if (!dbPool) return;
  try {
    await safeDbQuery(
      `INSERT INTO perfiles_empresa (id, student_id, company_name, description, logo_url, level, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       ON CONFLICT (id) DO UPDATE SET
         student_id = EXCLUDED.student_id,
         company_name = EXCLUDED.company_name,
         description = EXCLUDED.description,
         logo_url = EXCLUDED.logo_url,
         level = EXCLUDED.level,
         updated_at = EXCLUDED.updated_at`,
      [
        profile.id,
        profile.studentId,
        profile.companyName,
        profile.description || '',
        profile.logoUrl || '',
        profile.level || 1,
        profile.updatedAt || new Date().toISOString()
      ]
    );
  } catch (e) {
    console.error('[Supabase DB] Error syncing company profile to Supabase:', e);
  }
}

async function syncMarketContactToSupabase(contact: MarketContact) {
  if (!dbPool) return;
  try {
    await safeDbQuery(
      `INSERT INTO contactos_mercado (id, user_id, contact_id, created_at)
       VALUES ($1, $2, $3, $4)
       ON CONFLICT (user_id, contact_id) DO NOTHING`,
      [contact.id, contact.userId, contact.contactId, contact.createdAt || new Date().toISOString()]
    );
  } catch (e) {
    console.error('[Supabase DB] Error syncing market contact to Supabase:', e);
  }
}

