// Supabase Status Endpoint
app.get('/api/supabase-status', async (req, res) => {
  if (!dbPool) {
    return res.json({ 
      connected: false, 
      message: 'DATABASE_URL no está configurada',
      dbUrlMasked: ''
    });
  }
  try {
    const resCuentas = await safeDbQuery('SELECT COUNT(*) FROM cuentas');
    const resMov = await safeDbQuery('SELECT COUNT(*) FROM movimientos');
    res.json({
      connected: Boolean(resCuentas),
      cuentasCount: resCuentas?.rows?.[0]?.count ? Number(resCuentas.rows[0].count) : 0,
      movimientosCount: resMov?.rows?.[0]?.count ? Number(resMov.rows[0].count) : 0,
      dbUrlMasked: maskDbUrl(process.env.DATABASE_URL)
    });
  } catch (e: any) {
    res.json({ 
      connected: false, 
      error: e.message || String(e),
      dbUrlMasked: maskDbUrl(process.env.DATABASE_URL)
    });
  }
});

// Supabase Connect / Reconfigure Endpoint
app.post('/api/supabase-connect', async (req, res) => {
  const { url } = req.body;
  if (!url || typeof url !== 'string' || !url.trim()) {
    return res.status(400).json({ success: false, error: 'Proporciona una URL válida (DATABASE_URL)' });
  }

  const cleanUrl = url.trim();
  try {
    initPgPool(cleanUrl);
    const tableInit = await initSupabaseTables();
    if (!tableInit.success) {
      return res.status(500).json({ success: false, error: tableInit.error });
    }

    const restoreRes = await restoreFromSupabase();

    // Verify record counts
    let cuentasCount = 0;
    let movimientosCount = 0;
    if (dbPool) {
      const cRes = await safeDbQuery('SELECT COUNT(*) FROM cuentas');
      const mRes = await safeDbQuery('SELECT COUNT(*) FROM movimientos');
      cuentasCount = cRes?.rows?.[0]?.count ? Number(cRes.rows[0].count) : 0;
      movimientosCount = mRes?.rows?.[0]?.count ? Number(mRes.rows[0].count) : 0;
    }

    res.json({
      success: true,
      message: '¡Conectado a Supabase correctamente! Datos cargados y sincronizados desde la base de datos.',
      cuentasCount,
      movimientosCount,
      dbUrlMasked: maskDbUrl(cleanUrl)
    });
  } catch (e: any) {
    console.error('[Supabase Connect Error]', e);
    res.status(500).json({ success: false, error: e.message || String(e) });
  }
});

// Supabase Manual Sync Endpoint (Isolated & Advisory-Locked)
app.post('/api/supabase-sync', async (req, res) => {
  if (!dbPool) {
    return res.status(400).json({ success: false, error: 'DATABASE_URL no está configurada' });
  }
  const client = await dbPool.connect();
  try {
    await client.query('BEGIN');
    // Global advisory transaction lock to serialize with /api/restore and prevent concurrent race conditions
    await client.query('SELECT pg_advisory_xact_lock(987654321)');

    const tableInit = await initSupabaseTables();
    if (!tableInit.success) {
      await client.query('ROLLBACK');
      return res.status(500).json({ success: false, error: tableInit.error });
    }

    // Only seed from memory if PostgreSQL accounts table is empty (preventing destruction of PostgreSQL truth!)
    const countRes = await client.query('SELECT COUNT(*) FROM cuentas');
    const pgCount = parseInt(countRes.rows[0]?.count || '0', 10);
    if (pgCount === 0) {
      const currentDb = readDb();
      await syncAllToSupabase(currentDb);
    }

    await client.query('COMMIT');
  } catch (err: any) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('[Supabase Sync Error]', err);
    return res.status(500).json({ success: false, error: err.message || String(err) });
  } finally {
    client.release();
  }

  // After COMMIT, reconcile in-memory cache from PostgreSQL (single source of truth)
  await restoreFromSupabase();

  let cuentasCount = 0;
  let movimientosCount = 0;
  const cRes = await safeDbQuery('SELECT COUNT(*) FROM cuentas');
  const mRes = await safeDbQuery('SELECT COUNT(*) FROM movimientos');
  cuentasCount = cRes?.rows?.[0]?.count ? Number(cRes.rows[0].count) : 0;
  movimientosCount = mRes?.rows?.[0]?.count ? Number(mRes.rows[0].count) : 0;

  res.json({
    success: true,
    message: 'Sincronización y conciliación con PostgreSQL/Supabase completada con éxito (fuente de verdad protegida).',
    cuentasCount,
    movimientosCount
  });
});

// Authenticate / Login
const loginHandler = async (req: express.Request, res: express.Response) => {
  const { username, password } = req.body;
  
  console.log('[LOGIN] Request received. Username:', username, 'Password:', password ? '****' : 'empty');

  const cleanUsername = String(username || '').trim().toLowerCase();
  const cleanPassword = String(password || '').trim();
  const strippedUsername = cleanUsername.replace(/[^a-z0-9]/gi, '');

  // Log to database systemLogs for diagnostic tracking
  try {
    const db = readDb();
    const newLog: SystemLog = {
      id: generateId('log-debug'),
      action: 'LOGIN_ATTEMPT',
      details: `Intento de acceso recibido: usuario "${cleanUsername || 'vacío'}".`,
      timestamp: new Date().toISOString()
    };
    db.systemLogs.unshift(newLog);
    writeDb(db);
  } catch (e) {
    console.error('Failed to write login attempt log:', e);
  }

  if (!cleanUsername || !cleanPassword) {
    console.log('[LOGIN] Failed: Missing username or password');
    return res.status(400).json({ error: 'Usuario y contraseña requeridos' });
  }

  const db = readDb();
  let user = db.users.find(u => {
    const uName = (u.username || '').trim().toLowerCase();
    const uPass = (u.password || '').trim();
    const nameMatch = (u.name || '').trim().toLowerCase() === cleanUsername;
    const accountMatch = (u.accountNumber || '').trim().toLowerCase() === cleanUsername;
    const idMatch = (u.id || '').trim().toLowerCase() === cleanUsername;
    const strippedMatch = uName.replace(/[^a-z0-9]/gi, '') === strippedUsername;
    const isPasswordValid = uPass === cleanPassword || (!uPass && cleanPassword === '123');
    return (uName === cleanUsername || nameMatch || accountMatch || idMatch || strippedMatch) && isPasswordValid;
  });

  // If not found in local db, query Supabase directly if connected
  if (!user && dbPool) {
    try {
      const queryRes = await safeDbQuery(
        `SELECT * FROM cuentas WHERE LOWER(usuario) = $1 OR LOWER(alumno) = $1 OR LOWER(account_number) = $1 OR LOWER(id) = $1 LIMIT 1`,
        [cleanUsername]
      );
      if (queryRes && queryRes.rows.length > 0) {
        const row = queryRes.rows[0];
        const dbPass = (row.password || '123').trim();
        if (dbPass === cleanPassword || (!row.password && cleanPassword === '123')) {
          const newUser: User = {
            id: String(row.id),
            name: String(row.alumno),
            username: row.usuario ? String(row.usuario) : cleanUsername,
            password: dbPass,
            role: (row.role as any) || 'student',
            accountNumber: row.account_number || generateIBAN(),
            balance: Number(row.saldo) || 0,
            level: row.level ? (Number(row.level) as 1 | 2 | 3) : 1
          };
          const existingIdx = db.users.findIndex(u => u.id === newUser.id);
          if (existingIdx >= 0) {
            db.users[existingIdx] = newUser;
          } else {
            db.users.push(newUser);
          }
          writeDb(db);
          user = newUser;
        }
      }
    } catch (sbErr) {
      console.error('[Supabase Login Query Error]', sbErr);
    }
  }

  if (!user) {
    console.log('[LOGIN] Failed: Credentials do not match any active user. Username tried:', cleanUsername);
    return res.status(401).json({ error: 'Credenciales inválidas. Comprueba tu usuario y contraseña.' });
  }

  console.log('[LOGIN] Success! Matched user:', user.name, 'Role:', user.role);

  // Exclude password from response
  const { password: _, ...userWithoutPassword } = user;
  res.json({ user: userWithoutPassword });
};

app.post('/api/login', loginHandler);
app.post('/api/auth/login', loginHandler);
app.post('/api/acceso', loginHandler);
app.post('/api/entrar', loginHandler);
app.post('/acceso', loginHandler);
app.post('/entrar', loginHandler);
app.post('/login', loginHandler);

// Get users list
// Note: If teacher, returns full details (with passwords so they can hand them out!).
// If student, returns limited public info (name, username, accountNumber) for transfer targets.
const handleGetUsersRoute = async (req: express.Request, res: express.Response) => {
  const role = req.query.role as string;
  const bypass = req.headers['x-bypass-cache'] === 'true' || req.query.fresh === 'true';
  const now = Date.now();

  if (!bypass && role !== 'teacher' && globalCatalogCache.users && (now - globalCatalogCache.users.cachedAt < 30000)) {
    totalSessionCacheHits++;
    return res.json(globalCatalogCache.users.data);
  }
  totalSessionCacheMisses++;

  const db = readDb();
  let usersList = (db.users || []).map(u => ({ ...u }));

  if (dbPool) {
    try {
      const resCuentas = await safeDbQuery('SELECT * FROM cuentas ORDER BY alumno ASC');
      if (resCuentas && resCuentas.rows && resCuentas.rows.length > 0) {
        for (const row of resCuentas.rows) {
          const rowId = String(row.id);
          const existing = usersList.find(u => u.id === rowId || (row.usuario && u.username.toLowerCase() === String(row.usuario).toLowerCase()));
          if (existing) {
            existing.balance = Number(row.saldo !== undefined ? row.saldo : existing.balance);
            if (row.password) existing.password = String(row.password);
            if (row.level) existing.level = Number(row.level) as 1 | 2 | 3;
            if (row.alumno) existing.name = String(row.alumno);
            if (row.account_number) existing.accountNumber = String(row.account_number);
          } else if (row.rol !== 'teacher' && row.usuario) {
            usersList.push({
              id: rowId,
              username: String(row.usuario).toLowerCase(),
              password: String(row.password || '123'),
              role: 'student',
              name: String(row.alumno || row.usuario),
              accountNumber: String(row.account_number || generateIBAN()),
              balance: Number(row.saldo || 0),
              level: Number(row.level || 1) as 1 | 2 | 3
            });
          }
        }
      }
    } catch (e) {
      console.warn('[Supabase Real-Time Read Warning for Users]:', e);
    }
  }

  if (role === 'teacher') {
    res.json({ users: usersList, instanceId: SERVER_INSTANCE_ID, isSeed: db.isSeed || false, supabaseConnected: !!dbPool });
  } else {
    // Only return students and filter out password/admin details
    const publicStudents = usersList
      .filter(u => u.role === 'student')
      .map(({ password: _, ...u }) => u);
    globalCatalogCache.users = { data: { users: publicStudents }, cachedAt: Date.now() };
    res.json({ users: publicStudents });
  }
};

app.get('/api/users', handleGetUsersRoute);
app.get('/users', handleGetUsersRoute);

// Create new bank user account (Teacher only)
const handleCreateUserRoute = async (req: express.Request, res: express.Response) => {
  const { name, username, password, initialBalance, level } = req.body;

  if (!name || !username || !password) {
    return res.status(400).json({ error: 'Nombre, usuario y contraseña son requeridos' });
  }

  const cleanUsername = username.toLowerCase().trim();
  const db = readDb();
  const exists = db.users.some(u => u.username.toLowerCase() === cleanUsername);
  
  if (exists) {
    return res.status(400).json({ error: 'El nombre de usuario ya existe' });
  }

  const userLevel = (level && [1, 2, 3].includes(Number(level))) ? (Number(level) as 1 | 2 | 3) : 1;
  const initialBal = Number(initialBalance) || 0;

  const newUser: User = {
    id: generateId('user'),
    username: cleanUsername,
    password: password.trim(),
    role: 'student',
    name: name.trim(),
    accountNumber: generateIBAN(),
    balance: initialBal,
    level: userLevel
  };

  if (dbPool) {
    try {
      await withPostgresTransaction(async (client) => {
        // Advisory xact lock to serialize concurrent creation of identical username
        await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', ['user_creation_' + cleanUsername]);

        const checkRes = await client.query(
          'SELECT id FROM cuentas WHERE LOWER(usuario) = LOWER($1) OR id = $2',
          [cleanUsername, newUser.id]
        );
        if (checkRes.rows.length > 0) {
          const err: any = new Error('El nombre de usuario ya existe en la base de datos');
          err.statusCode = 400;
          throw err;
        }

        await client.query(
          `INSERT INTO cuentas (id, alumno, saldo, usuario, password, account_number, role, level)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
          [newUser.id, newUser.name, newUser.balance, newUser.username, newUser.password, newUser.accountNumber, newUser.role, newUser.level]
        );

        if (initialBal > 0) {
          const txId = generateId('tx');
          await client.query(
            `INSERT INTO movimientos (id, cuenta_id, tipo, importe, fecha, concepto, sender_id, sender_name, sender_account, receiver_id, receiver_name, receiver_account)
             VALUES ($1, $2, 'DEPOSIT', $3, $4, $5, $6, $7, $8, $9, $10, $11)`,
            [
              txId + '-in',
              newUser.id,
              initialBal,
              new Date().toISOString(),
              'Saldo inicial de apertura de cuenta',
              'corp-banco-central',
              'Banco Central Mercantil',
              'ES210001000299887700',
              newUser.id,
              newUser.name,
              newUser.accountNumber
            ]
          );
        }
      });
    } catch (err: any) {
      console.error('[Create User Transaction Error]:', err);
      return res.status(err.statusCode || 500).json({ error: err.message || 'Error al crear usuario en la base de datos' });
    }
  }

  db.users.push(newUser);

  const newLog: SystemLog = {
    id: generateId('log'),
    action: 'CREATE_USER',
    details: `Cuenta creada: ${newUser.name} (${newUser.username}) - Nivel ${newUser.level} con saldo inicial de ${newUser.balance} €`,
    timestamp: new Date().toISOString()
  };
  db.systemLogs.unshift(newLog);

  writeDb(db);
  res.status(201).json({ user: newUser });
};

app.post('/api/users', handleCreateUserRoute);
