    const user = db.users?.find(u => u.id === sId || u.username === sId);
    const matchedIds = new Set<string>();
    if (sId) matchedIds.add(sId);
    if (user) {
      if (user.id) matchedIds.add(user.id);
      if (user.username) matchedIds.add(user.username);
    }
